types.prepare:
// The card only sees the character; the code and mnemonic stay in the key until grading.
return {
  view: { letter: fields.letter, name: fields.name ?? "", prosign: !!fields.prosign },
  key: { code: fields.code, mnemonic: fields.mnemonic ?? "" },
};

template.css:
/* Etude 3 card look, as in the Design Lab round 06: a grey tracked eyebrow. The verdict pill comes from the study screen. */
.c3-eyebrow { font-size: 12px; font-weight: 700; letter-spacing: 0.13em; text-transform: uppercase; color: var(--muted-foreground); }

.mo:focus { outline: none; }
.mo { display: flex; flex-direction: column; align-items: center; text-align: center; padding: 8px 0 4px; --ink: var(--foreground); --no: light-dark(#a1382a, #f0937e); }
[data-mode="result"] .mo { padding-top: 0; }
.mo-letter { font: 600 120px/1 "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif; margin: 16px 0 10px; }
.mo-letter.is-prosign { line-height: 0.8; border-top: 0.06em solid currentColor; padding-top: 0.04em; }
.mo-name { color: var(--muted-foreground); font-size: 15px; margin: -4px 0 8px; }

/* Dots and dashes: plain ink pills. */
.mo-code { height: 44px; display: flex; gap: 12px; justify-content: center; align-items: center; }
.mo-code i { display: block; flex: none; background: var(--ink); border-radius: 999px; }
.mo-code .dot { width: 16px; height: 16px; }
.mo-code .dash { width: 50px; height: 16px; }
.mo-code .new { animation: mo-in 0.22s cubic-bezier(.2, .8, .2, 1); }
.mo-code.long { gap: 9px; }
.mo-code.long .dash { width: 40px; }
.mo-code .ph { color: var(--muted-foreground); font-size: 16px; }
.mo-code.big .dot { width: 22px; height: 22px; }
.mo-code.big .dash { width: 68px; height: 22px; }
.mo-code.big.long .dash { width: 52px; }
@keyframes mo-in { 0% { transform: scale(0.4); opacity: 0; } 100% { transform: none; opacity: 1; } }

/* The key: one round button you tap for a dot and hold for a dash. */
.mo-key { all: unset; cursor: pointer; margin: 22px auto 12px; width: 150px; height: 150px; border-radius: 50%; display: grid; place-items: center; color: var(--ink); font: 600 15px var(--font-sans); user-select: none; -webkit-user-select: none; -webkit-tap-highlight-color: transparent; touch-action: manipulation;
  background: light-dark(#f4f4f2, #222222); box-shadow: 0 6px 0 var(--border), 0 0 0 1px light-dark(var(--border), transparent), 0 14px 30px light-dark(rgba(0, 0, 0, 0.07), rgba(0, 0, 0, 0.45)); transition: transform 0.05s, box-shadow 0.05s; }
.mo-key:focus-visible { outline: 2px solid var(--ring); outline-offset: 4px; }
.mo-key.down { transform: translateY(5px); box-shadow: 0 1px 0 var(--border), 0 0 0 1px light-dark(var(--border), transparent), 0 8px 18px light-dark(rgba(0, 0, 0, 0.07), rgba(0, 0, 0, 0.45)); }
.mo-hint { font-size: 15px; color: var(--muted-foreground); display: flex; align-items: center; justify-content: center; gap: 10px; min-height: 30px; }
.mo-del { all: unset; cursor: pointer; font-size: 17px; line-height: 1; padding: 6px 8px; border-radius: 8px; color: var(--muted-foreground); visibility: hidden; }
.mo-del.on { visibility: visible; }
.mo-del:hover { color: var(--ink); background: color-mix(in srgb, var(--foreground) 7%, transparent); }

/* After checking: the right code blinks, yours (when wrong) sits under it in red. */
.mo-correct { margin-top: 2px; }
.mo-correct.blink i { animation: mo-bl 2.4s 1s infinite backwards; }
.mo-correct.blink i:nth-child(2) { animation-delay: 1.25s; }
.mo-correct.blink i:nth-child(3) { animation-delay: 1.5s; }
.mo-correct.blink i:nth-child(4) { animation-delay: 1.75s; }
.mo-correct.blink i:nth-child(5) { animation-delay: 2s; }
.mo-correct.blink i:nth-child(n+6) { animation-delay: 2.25s; }
@keyframes mo-bl { 0%, 100% { opacity: 1; } 10% { opacity: 0.25; } }
.mo-yours { margin-top: 16px; font-size: 15px; color: var(--muted-foreground); display: flex; gap: 12px; justify-content: center; align-items: center; }
.mo-yours[hidden] { display: none; }
.mo-sent { height: auto; display: inline-flex; gap: 8px; }
.mo-sent i { background: var(--no); }
.mo-sent .dot { width: 12px; height: 12px; }
.mo-sent .dash { width: 36px; height: 12px; }
.mo-sub { font-size: 16px; color: var(--muted-foreground); margin-top: 16px; max-width: 52ch; }
.mo-sub strong { color: var(--ink); }

@media (max-width: 520px) { .mo-letter { font-size: 104px; } .mo-key { width: 140px; height: 140px; } }
@media (prefers-reduced-motion: reduce) { .mo-correct.blink i, .mo-code .new { animation: none !important; } }

template.js:
const mine = etude.$(".mo-mine");
const key = etude.$(".mo-key");
const del = etude.$(".mo-del");
if (etude.view.prosign) etude.$(".mo-letter").classList.add("is-prosign");
const MAX = 9; // the longest code here is SOS, ...---...
const HOLD = 220; // a press longer than this is a dash
let seq = typeof etude.answer === "string" ? etude.answer : "";
const sym = (s, cls = "") => `<i class="${s === "." ? "dot" : "dash"}${cls ? " " + cls : ""}"></i>`;
const touch = matchMedia("(pointer: coarse)").matches;
etude.$(".mo-hint-text").textContent = touch ? "Short tap for a dot, hold for a dash" : "Short press for a dot, hold for a dash · or type . and -";

const draw = (fresh) => {
  mine.innerHTML = seq ? [...seq].map((s, i) => sym(s, fresh && i === seq.length - 1 ? "new" : "")).join("") : `<span class="ph">dots and dashes appear here</span>`;
  mine.classList.toggle("long", seq.length > 6);
  del.classList.toggle("on", seq.length > 0);
  etude.setReady(seq.length > 0);
};
const press = (s) => {
  if (etude.mode !== "answer") return;
  seq = s === "del" ? seq.slice(0, -1) : (seq + s).slice(0, MAX);
  draw(s !== "del");
};

// The key: how long you hold it decides dot or dash, like a real straight key.
let down = 0;
key.addEventListener("pointerdown", (e) => {
  if (etude.mode !== "answer" || e.button > 0) return;
  down = performance.now();
  key.classList.add("down");
  try { key.setPointerCapture(e.pointerId); } catch {}
});
const up = (e, cancel) => {
  if (!down) return;
  const held = performance.now() - down;
  down = 0;
  key.classList.remove("down");
  // A long hold on a phone can end in pointercancel (the system's long-press); it still counts as a dash.
  if (!cancel || held >= HOLD) press(held < HOLD ? "." : "-");
};
key.addEventListener("pointerup", (e) => up(e, false));
key.addEventListener("pointercancel", (e) => up(e, true));
key.addEventListener("click", (e) => e.preventDefault());
key.addEventListener("contextmenu", (e) => e.preventDefault());
del.addEventListener("click", () => press("del"));

const flash = () => { key.classList.add("down"); setTimeout(() => key.classList.remove("down"), 110); };
window.addEventListener("keydown", (e) => {
  const s = { ".": ".", "-": "-", j: ".", k: "-", Backspace: "del" }[e.key];
  if (!s || etude.mode !== "answer" || e.ctrlKey || e.metaKey || e.altKey) return;
  e.preventDefault();
  press(s);
  if (s !== "del") flash();
});
draw(false);
etude.getAnswer(() => seq);

etude.onResult(({ grade, key: k, answer }) => {
  const sent = String(answer ?? seq ?? "").replace(/[^.-]/g, "");
  const code = String(k.code ?? "");
  const ok = (grade?.score ?? (sent === code ? 1 : 0)) >= 1;
  const right = etude.$(".mo-correct");
  right.innerHTML = [...code].map((s) => sym(s)).join("");
  right.classList.toggle("long", code.length > 6);
  if (!matchMedia("(prefers-reduced-motion: reduce)").matches) right.classList.add("blink");
  if (!ok) {
    const yours = etude.$(".mo-yours");
    yours.hidden = false;
    etude.$(".mo-sent").innerHTML = sent ? [...sent].map((s) => sym(s)).join("") : "nothing";
  }
});

grader.code:
// answer is the tapped sequence, e.g. "-.-."
const sent = String(answer ?? "").replace(/[^.-]/g, "");
const ok = sent === key.code;
return {
  score: ok ? 1 : 0,
  details: { sent },
  feedback: ok ? undefined : `You sent ${sent || "nothing"}, but ${view.letter} is ${key.code}`,
};
